variants.code_sketch:
const moved = {
  ...person,
  home: { ...person.home, city: 'Berlin' },
};

// deep, when sharing must be excluded entirely:
const detached = structuredClone(person);
detached.home.city = 'Berlin';

import * as R from 'ramda';

const homeCity = R.lensPath(['home', 'city']);

R.view(homeCity, person);            // 'London'
R.set(homeCity, 'Berlin', person);   // new person, original untouched
R.over(homeCity, s => s.toUpperCase(), person);
